<?php $pageTitle='Presupuestos'; ?><section class="page-head"><div><p class="eyebrow">Control de gastos</p><h1>Presupuestos</h1><p class="muted">Define límites y mira cuánto te queda disponible.</p></div></section><div class="panel"><div class="panel-title"><h2>Crear presupuesto</h2></div><form class="form-grid" method="post" action="index.php?url=budget/save"><input type="hidden" name="csrf" value="<?=$csrf?>"><label>Nombre<input name="name" placeholder="Ej. Maquillaje" required></label><label>Categoría<input name="category" placeholder="Compras" required></label><label>Límite<input type="number" name="limit_amount" min="1" required></label><label>Periodo<select name="period"><option value="weekly">Semanal</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></label><label>Gasto inicial<input type="number" name="initial_spent" min="0" value="0"></label><button class="btn primary">Crear presupuesto</button></form></div><div class="budget-grid"><?php foreach($budgets as $b): $spent=(float)$b['spent']+(float)$b['initial_spent'];$remaining=max(0,(float)$b['limit_amount']-$spent);$p=min(100,$spent/$b['limit_amount']*100); ?><article class="panel budget-card"><div class="goal-top"><div><span class="goal-icon">▣</span><h2><?=htmlspecialchars($b['name'])?></h2><p class="muted"><?=htmlspecialchars($b['category'])?> · <?=['weekly'=>'Semanal','monthly'=>'Mensual','yearly'=>'Anual'][$b['period']]?></p></div><div class="goal-actions"><button class="icon-btn" onclick="toggleModal('budget-<?=$b['id']?>')">✎</button><form method="post" action="index.php?url=budget/delete" onsubmit="return confirm('¿Eliminar presupuesto?')"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="icon-btn danger">×</button></form></div></div><div class="goal-numbers"><strong>$<?=number_format($spent,0,',','.')?></strong><span>gastado de $<?=number_format($b['limit_amount'],0,',','.')?></span></div><div class="progress"><i style="width:<?=$p?>%"></i></div><div class="goal-meta"><span>Quedan $<?=number_format($remaining,0,',','.')?></span><span><?=number_format($p,0)?>%</span></div><form class="inline-form" method="post" action="index.php?url=budget/expense"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="budget_id" value="<?=$b['id']?>"><input type="number" name="amount" min="1" placeholder="Gasto" required><input type="date" name="date" value="<?=date('Y-m-d')?>" required><input name="description" placeholder="¿En qué gastaste?"><button class="btn primary">Agregar gasto</button></form><details><summary>Ver últimos gastos</summary><div class="mini-table"><?php foreach(array_slice(($details[$b['id']]??[]),0,7) as $e): ?><div><span><?=date('d/m/Y',strtotime($e['date']))?> · <?=htmlspecialchars($e['description']??'Gasto')?></span><strong>-$<?=number_format($e['amount'],0,',','.')?></strong><a class="text-edit" href="index.php?url=budget/editExpense&id=<?=$e['id']?>">Editar</a><form method="post" action="index.php?url=budget/deleteExpense"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$e['id']?>"><button class="text-danger">Eliminar</button></form></div><?php endforeach; if(empty($details[$b['id']])): ?><p class="muted">No hay gastos registrados.</p><?php endif; ?></div></details><div id="budget-<?=$b['id']?>" class="modal"><div class="modal-box"><button onclick="toggleModal('budget-<?=$b['id']?>')" class="close">×</button><h2>Editar presupuesto</h2><form class="form-grid" method="post" action="index.php?url=budget/edit"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$b['id']?>"><label>Nombre<input name="name" value="<?=htmlspecialchars($b['name'])?>"></label><label>Categoría<input name="category" value="<?=htmlspecialchars($b['category'])?>"></label><label>Límite<input type="number" name="limit_amount" value="<?=$b['limit_amount']?>"></label><label>Periodo<select name="period"><option value="weekly" <?=$b['period']==='weekly'?'selected':''?>>Semanal</option><option value="monthly" <?=$b['period']==='monthly'?'selected':''?>>Mensual</option><option value="yearly" <?=$b['period']==='yearly'?'selected':''?>>Anual</option></select></label><label>Gasto inicial<input type="number" name="initial_spent" value="<?=$b['initial_spent']?>"></label><button class="btn primary">Guardar</button></form></div></div></article><?php endforeach; ?></div>